# Contenu des pages conducteur et demande. Les réponses et critères restent à valider avant publication.
F=lambda n,l,t='text',rq=True,x='':f'<div class="fd"><label for="{n}">{l}{"" if rq else " <small>(facultatif)</small>"}</label><input id="{n}" name="{n}" type="{t}" {"required" if rq else ""} {x}><p class="er" id="{n}-e"></p></div>'
CON='<div class="fd ck"><label><input type="checkbox" name="consent" required> <span>J\'accepte que ROAM utilise ces informations pour me recontacter. <a href="../../premium-v2/confidentialite/">Données personnelles</a></span></label><p class="er" id="consent-e"></p></div><input class="hp" name="website" tabindex="-1" autocomplete="off" aria-hidden="true">'
ST='<p class="st" role="status" data-st></p>'
I='../img/'
PH2=lambda top,tt,items,btn='':f'<div class="ph" aria-hidden="true"><div class="sc"><div class="ps" style="display:block"><div class="pscr">{BAR}<small>{top}</small><strong class="h">{tt}</strong><ul class="chk">'+''.join(f'<li class="{c}">{x}</li>' for x,c in items)+f'</ul>{btn}</div></div></div></div>'
M1='<div class="med">'+PH2('Candidature','Mon profil',[('Mes coordonnées','ok'),('Ma voiture','ok'),('Ma zone','')],'<div class="pbtn">Envoyer</div>')+'</div>'
M2=f'<div class="med two"><figure><img loading="lazy" src="{I}d_a2_0.webp" alt="Détail de la voiture" width="760" height="500"></figure><figure><img loading="lazy" src="{I}d_a1_0.webp" alt="Rétroviseur et porte" width="760" height="500"></figure></div>'
M3=f'<div class="med"><img loading="lazy" src="{I}p_city.webp" alt="Une ville vue du ciel" width="1600" height="900"></div>'
M4=f'<div class="med"><div class="cvc"><img src="{I}s_a1.webp" alt="La voiture blanche avant la pose" width="2200" height="1238"><img class="top" src="{I}s_b1.webp" alt="La même voiture après la pose" width="2200" height="1238"><i class="sq"></i></div></div>'
M5=f'<div class="med"><img loading="lazy" src="{I}p_car.webp" alt="La voiture habillée dans une rue" width="1600" height="900"></div>'
M6='<div class="med">'+PH2('Conducteur','Mon mois',[('Kilomètres validés','ok'),('Grandes zones','ok'),('Critères du contrat','')],'<div class="pbtn">Valider mon mois</div>')+'</div>'
STEPS=[('Inscription','Vous remplissez le formulaire en quelques minutes.','Vos coordonnées, votre voiture et votre zone','Enregistre votre candidature','Une inscription ne garantit pas une campagne',M1),
 ('Vérification','Nous regardons votre profil et l\'état de votre voiture.','Vous répondez à quelques questions','Contrôle le modèle, l\'état et l\'usage','Les critères définitifs seront précisés à ce moment',M2),
 ('Sélection','Si une campagne correspond à votre zone, nous vous contactons.','Vous acceptez ou non la proposition','Présente la campagne et les conditions','Tout dépend des besoins des annonceurs',M3),
 ('Pose','Le covering est posé par des professionnels.','Vous déposez la voiture au rendez-vous','Organise la pose du film','Les vitres restent libres',M4),
 ('Circulation','Vous roulez comme d\'habitude, selon les conditions convenues.','Vous gardez vos trajets habituels','Suit les kilomètres et les grandes zones','Pas de suivi détaillé de vos trajets',M5),
 ('Rémunération','Les critères sont validés, puis vous êtes rémunéré selon le contrat.','Vous validez votre mois dans l\'application','Contrôle les critères du contrat','Le montant dépend de la campagne et du contrat',M6)]
COL=[('var(--bg)','var(--ink)'),('var(--sig)','var(--sigt)'),('var(--bg2)','var(--ink)')]
FY=''.join(f'''<article class="fy" style="--c:{COL[i%3][0]};--ct:{COL[i%3][1]}"><h3 class="mega lg2">{t}</h3><div class="fb one"><div class="inf"><p class="say">{i+1}/6 · {d}</p><dl><dt>Vous</dt><dd>{a}</dd><dt>ROAM</dt><dd>{b}</dd><dt>À savoir</dt><dd>{c}</dd></dl></div>{m}</div></article>''' for i,(t,d,a,b,c,m) in enumerate(STEPS))
FAQ=[('Est-ce que le covering abîme la voiture ?','Un film posé et retiré dans de bonnes conditions protège généralement la peinture. L\'état de votre carrosserie sera vérifié avant la pose.'),
 ('Qui s\'occupe de la pose et du retrait ?','ROAM organise la pose et le retrait avec des professionnels, aux conditions prévues dans le contrat.'),
 ('Que se passe-t-il pour mon assurance ?','Les démarches éventuelles seront précisées avant la signature. Votre situation sera regardée au cas par cas.'),
 ('Quelles sont mes obligations ?','Garder la voiture en bon état, rouler selon les conditions convenues et valider vos kilomètres dans l\'application.'),
 ('Mon trajet est-il suivi en détail ?','Non, le principe est de valider des kilomètres et de grandes zones, pas chacun de vos trajets. La méthode exacte sera précisée dans le contrat.'),
 ('Suis-je sûr d\'avoir une campagne ?','Non. La candidature vous inscrit sur notre liste de conducteurs intéressés. Une campagne dépend de votre zone, de votre voiture et des besoins des annonceurs.')]
CR=[('Votre voiture','Modèle, année et kilométrage.','','',E[0][4]),('Son état','Une carrosserie propre, sans gros dégâts.','','',E[1][4]),('Votre zone','Les villes et secteurs où vous roulez.','','',E[2][4]),('Votre usage','Votre rythme de déplacement.','','',E[3][4])]
CRM=[['Voitures de particuliers','Flottes d\'entreprise','Critères précisés à la candidature'],['Peinture en bon état','Pas de gros choc','Contrôle avant la pose'],['Grandes villes','Périphérie','Selon les campagnes ouvertes'],['Trajets réguliers','Kilomètres par mois','Pas besoin de changer vos habitudes']]
BTNC='<a class="btn" href="#candidature"><span class="rl" data-t="Déposer ma candidature">Déposer ma candidature</span></a><a class="lnk" href="#etapes">Comment ça marche</a>'
ST0=STK('Devenir conducteur','Vous roulez déjà. Votre voiture peut vous rapporter.','Acceptez une publicité sur votre voiture et recevez une rémunération, selon les conditions du programme.',[('Simple','Vous gardez vos habitudes. Nous gérons le visuel et la pose.'),('Encadré','Un contrat fixe clairement les conditions du programme.'),('Honnête','La rémunération dépend de la campagne : elle n\'est jamais garantie d\'avance.')],
 [('Vous acceptez','Une campagne vous est proposée, vous restez libre de dire non.','p_car',[('Une proposition claire','Le visuel, la durée et les conditions.'),('Un contrat','Tout est écrit avant la pose.'),('Votre voiture reste la vôtre','Vous l\'utilisez normalement.')]),('Nous posons','Le film est posé par des professionnels, puis retiré en fin de campagne.','p_msg',[('Un visuel soigné','Créé pour votre modèle de voiture.'),('Les vitres libres','Rien sur les vitres ni sur les feux.'),('Un retrait prévu','Aux conditions du contrat.')]),('Vous roulez','Vous continuez vos trajets, et la campagne circule avec vous.','p_city',[('Vos trajets habituels','Rien à changer au quotidien.'),('Vos kilomètres','À valider dans l\'application.'),('Votre rémunération','Selon les conditions du programme.')])]).replace('IMG/',I)
D=f'''<div data-sec="hero"><section class="h1g" aria-label="Présentation"><h1><span class="ln"><span>Votre voiture,</span></span><span class="ln"><span>en campagne.</span></span></h1><div class="art"><img src="{I}s_b1.webp" alt="Berline habillée en noir et blanc" width="2200" height="1238"></div><div class="foot"><p>Recevez une rémunération pour une publicité sur votre voiture, selon les conditions du programme.</p>{BTNC}</div></section></div>
<div data-sec="concept">{ST0}</div>
<div data-sec="formats" id="etapes"><header class="sh sb"><p class="eye">Comment ça marche</p><h2 class="big">Six étapes, du formulaire à la route</h2><p class="lead2">Un parcours simple, avec un point de contrôle à chaque étape. Vous savez toujours ce que vous avez à faire, et ce que fait ROAM.</p></header><section class="f2"><div class="fst">{FY}</div></section></div>
<section class="sim ovl" aria-labelledby="si-t"><div><p class="eye">Combien peut-on gagner ?</p><h2 class="big" id="si-t">Une estimation, pas une promesse</h2><p class="lead2">Votre revenu dépend de la voiture, de la zone, de la campagne, des kilomètres éligibles et du contrat.</p><form class="sf" onsubmit="return false"><fieldset><legend>Votre zone</legend><div class="op"><label><input type="radio" name="z" value="1"><span>Zone rurale</span></label><label><input type="radio" name="z" value="2" checked><span>Périphérie</span></label><label><input type="radio" name="z" value="3"><span>Grande ville</span></label></div></fieldset><fieldset><legend>Format de campagne</legend><div class="op"><label><input type="radio" name="f" value="1"><span>Classique</span></label><label><input type="radio" name="f" value="2" checked><span>Medium</span></label><label><input type="radio" name="f" value="3"><span>Complet</span></label></div></fieldset><div class="rg"><label for="simkm">Kilomètres par mois <output id="kmo" for="simkm">1 000 km</output></label><input id="simkm" type="range" min="200" max="3000" step="100" value="1000"></div></form></div>
<div class="res" aria-live="polite"><p class="rl2">Niveau indicatif</p><strong id="lvl">Moyen</strong><div class="bar2"><i id="gau"></i></div><p class="amt" id="amt">Montant : à définir avant publication</p><p class="fine">Estimation indicative, jamais garantie. Aucune rémunération sans campagne et contrat signé.</p></div></section>
<div data-sec="expertise" class="noov"><section class="e1" data-v="1"><header class="sh"><p class="eye">Quels véhicules ?</p><h2 class="big">Ce que nous regardons</h2></header><div class="deck">{tkx("cl",CR,CRM)}</div></section></div>
<section class="faq ovl2" aria-labelledby="fa-t"><div><p class="eye">Vos questions</p><h2 class="big" id="fa-t">Avant de vous lancer</h2></div><div class="fql">{''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in FAQ)}</div></section>
<section class="cand" id="candidature" aria-labelledby="ca-t"><div class="cah"><p class="eye">Candidature</p><h2 class="big" id="ca-t">Rejoignez la liste des conducteurs</h2><p class="lead2">Une candidature ne garantit pas une campagne immédiate. Nous vous recontactons si une campagne correspond à votre zone et à votre voiture.</p></div>
<form class="fm" data-form="driverEndpoint" novalidate><div class="g2">{F('name','Nom et prénom')}{F('email','E-mail','email')}{F('phone','Téléphone','tel')}{F('city','Ville ou région')}{F('car','Marque et modèle du véhicule')}{F('year','Année du véhicule','number',True,'min="1990" max="2027" inputmode="numeric"')}{F('km','Kilométrage approximatif','number',True,'min="0" inputmode="numeric"')}</div><div class="fd"><label for="info">Informations complémentaires <small>(facultatif)</small></label><textarea id="info" name="info" rows="3"></textarea></div>{CON}<button class="btn" type="submit">Envoyer ma candidature</button>{ST}</form></section>'''
END='<section class="wrapc" aria-labelledby="k-t"><div class="cta"><h2 id="k-t">Votre voiture prend la route avec nous&nbsp;?</h2><p>Déposez votre candidature, nous vous recontactons si une campagne correspond.</p><div class="ct2"><a class="btn inv" href="#candidature"><span class="rl" data-t="Déposer ma candidature">Déposer ma candidature</span></a><a class="btn gh" href="../demande/"><span class="rl" data-t="Créer ma campagne">Créer ma campagne</span></a></div></div></section>'
page('conducteur','Devenir conducteur','Recevez une rémunération pour une publicité sur votre voiture, selon les conditions du programme ROAM.',D,'<script src="../app.js"></script><script src="../conducteur.js"></script>',END)
L=f'''<section class="cand dm" aria-labelledby="de-t"><div class="cah"><p class="eye">Créer ma campagne</p><h1 class="big" id="de-t">Parlons de votre campagne</h1><p class="lead2">Dites-nous ce que vous voulez faire connaître et où. Nous revenons vers vous avec une proposition.</p></div>
<form class="fm" data-form="quoteEndpoint" novalidate><div class="g2">{F('name','Nom et prénom')}{F('company','Entreprise')}{F('email','E-mail','email')}{F('phone','Téléphone','tel',False)}{F('zones','Villes ou zones visées')}<div class="fd"><label for="format">Format envisagé <small>(facultatif)</small></label><select id="format" name="format"><option value="">Je ne sais pas encore</option><option>Classique</option><option>Medium</option><option>Complet</option></select></div></div><div class="fd"><label for="message">Votre projet <small>(facultatif)</small></label><textarea id="message" name="message" rows="3"></textarea></div>{CON}<button class="btn" type="submit">Envoyer ma demande</button>{ST}</form></section>'''
page('demande','Créer ma campagne','Demandez une proposition pour votre campagne de publicité sur véhicules.',L,'<script>document.documentElement.classList.remove("mo")</script>')
